package smp.aeternum.carpet.command;
import com.mojang.brigadier.CommandDispatcher;import net.minecraft.server.command.ServerCommandSource;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.text.Text;import smp.aeternum.carpet.AeternumCarpetSettings;import smp.aeternum.carpet.network.GuideNetworking;import static net.minecraft.server.command.CommandManager.literal;
public final class GuideCommand {private GuideCommand(){}public static void register(CommandDispatcher<ServerCommandSource>d){d.register(literal("guide").requires(s->AeternumCarpetSettings.commandGuide).executes(c->{ServerPlayerEntity p;try{p=c.getSource().getPlayerOrThrow();}catch(Exception e){c.getSource().sendError(Text.literal("Las guías se abren dentro del juego."));return 0;}GuideNetworking.send(p,true);return 1;}));}}
